/* A real appearance preference: Day, Night or automatic system appearance. */
(() => {
const system=matchMedia('(prefers-color-scheme: dark)'),button=document.querySelector('#soundless-theme'),desktop=document.querySelector('#desktop');if(!button||!desktop)return;
let preference='auto';try{const saved=localStorage.getItem('po-theme');if(['light','dark','auto'].includes(saved))preference=saved}catch{}
const icons={light:'<circle cx="12" cy="12" r="4"/><path d="M12 2V4M12 20V22M2 12H4M20 12H22M5 5L6.5 6.5M17.5 17.5L19 19M19 5L17.5 6.5M6.5 17.5L5 19"/>',dark:'<path d="M20.8 13.1A9 9 0 1110.9 3.2A7 7 0 0020.8 13.1Z"/>',auto:'<circle cx="12" cy="12" r="9"/><path d="M12 3A9 9 0 0112 21Z" fill="currentColor" stroke="none"/>'};
const wallpaper=document.createElement('div');wallpaper.className='alpine-wallpaper';wallpaper.setAttribute('aria-hidden','true');wallpaper.innerHTML='<div class="alpine-scene alpine-day"></div><div class="alpine-scene alpine-night"></div>';desktop.prepend(wallpaper);
// Same setting on the welcome screen: both images are loaded before first switch.
const login=document.querySelector('#login');if(login){const scene=wallpaper.cloneNode(true);scene.classList.add('alpine-login-scene');login.prepend(scene)}
for(const src of ['assets/alpine-day.webp','assets/alpine-night.webp']){const image=new Image();image.src=src;image.decode?.().catch(()=>{})}
const menu=document.createElement('div');menu.className='appearance-menu';menu.hidden=true;menu.setAttribute('role','menu');menu.setAttribute('aria-label','Desktop appearance');menu.innerHTML='<div class="appearance-heading"><span>Appearance</span><small id="appearance-summary"></small></div>'+[['light','Day','Sunlit slopes & light windows'],['dark','Night','Moonlit resort & dark windows'],['auto','Auto','Follows your device’s appearance']].map(([value,label,description])=>`<button role="menuitemradio" aria-checked="false" data-appearance="${value}"><span class="appearance-preview appearance-preview-${value}"></span><span><strong>${label}</strong><small>${description}</small></span><span class="appearance-check" aria-hidden="true">✓</span></button>`).join('');document.body.append(menu);
button.setAttribute('aria-haspopup','menu');button.setAttribute('aria-expanded','false');button.title='Appearance: Day, Night or Auto';
const themeMeta=document.querySelector('meta[name="theme-color"]');
function apply(){const dark=preference==='dark'||preference==='auto'&&system.matches;document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.dataset.appearance=preference;document.documentElement.style.colorScheme=dark?'dark':'light';document.body.classList.toggle('dark',dark);button.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${icons[preference]}</svg>`;button.setAttribute('aria-label',`Appearance: ${preference==='auto'?'Auto, currently ':''}${dark?'Night':'Day'}. Change appearance`);menu.querySelector('#appearance-summary').textContent=preference==='auto'?`Auto · ${dark?'Night':'Day'}`:dark?'Night':'Day';menu.querySelectorAll('[data-appearance]').forEach(b=>b.setAttribute('aria-checked',b.dataset.appearance===preference));if(themeMeta)themeMeta.content=dark?'#0b192d':'#dceaf5';}
function place(){const box=button.getBoundingClientRect(),rect=menu.getBoundingClientRect();menu.style.left=Math.max(10,Math.min(innerWidth-rect.width-10,box.right-rect.width))+'px';menu.style.top=Math.min(innerHeight-rect.height-10,box.bottom+12)+'px'}
function close(focus=false){menu.hidden=true;button.setAttribute('aria-expanded','false');if(focus)button.focus({preventScroll:true})}
button.onclick=e=>{e.stopPropagation();menu.hidden=!menu.hidden;button.setAttribute('aria-expanded',!menu.hidden);if(!menu.hidden){place();menu.querySelector(`[data-appearance="${preference}"]`).focus({preventScroll:true})}};
menu.addEventListener('click',e=>{const option=e.target.closest('[data-appearance]');if(!option)return;preference=option.dataset.appearance;try{localStorage.setItem('po-theme',preference)}catch{}apply();close(true)});
menu.addEventListener('keydown',e=>{const options=[...menu.querySelectorAll('[data-appearance]')],index=options.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();options[(index+(e.key==='ArrowDown'?1:-1)+options.length)%options.length].focus()}if(e.key==='Home'){e.preventDefault();options[0].focus()}if(e.key==='End'){e.preventDefault();options.at(-1).focus()}if(e.key==='Escape'){e.preventDefault();close(true)}if(e.key==='Tab')close()});
document.addEventListener('click',e=>{if(!menu.contains(e.target)&&!button.contains(e.target))close()});window.addEventListener('resize',()=>{if(!menu.hidden)place()});window.addEventListener('blur',()=>close());system.addEventListener('change',()=>{if(preference==='auto')apply()});window.addEventListener('storage',e=>{if(e.key==='po-theme'){preference=['light','dark','auto'].includes(e.newValue)?e.newValue:'auto';apply()}});
apply();
})();
